from fractions import Fraction

def annual_cashflow_price(cashflows,yield_per_year):
    if type(cashflows) is not list or not 1<=len(cashflows)<=30:
        raise ValueError("expected1..30annual cashflows")
    if type(yield_per_year) not in (int,Fraction) or not -1<yield_per_year<=1:
        raise ValueError("expected exact annual effective yield in(-1,1]")
    prior=0;has_positive=False
    for row in cashflows:
        if type(row) is not tuple or len(row)!=2:
            raise ValueError("expected(year,amount_cents)tuples")
        year,amount=row
        if type(year) is not int or not prior<year<=30 or type(amount) is not int or not 0<=amount<=100000000:
            raise ValueError("expected increasing integer years and bounded nonnegative integer cents")
        prior=year;has_positive|=amount>0
    if not has_positive:
        raise ValueError("expected at least one positive future cashflow")
    rate=Fraction(yield_per_year)
    return sum(Fraction(amount)/(1+rate)**year for year,amount in cashflows)

