def yield_bracket(cashflows,target_cents,lower,upper,tolerance,max_iterations):
    exact=(int,Fraction)
    if any(type(v) not in exact for v in (target_cents,lower,upper,tolerance)):
        raise ValueError("expected exact price/yield/tolerance values, excluding bool")
    if not 0<target_cents<=1000000000 or not -1<lower<upper<=1 or not 0<tolerance<=1:
        raise ValueError("invalid price/rate bracket/tolerance")
    if type(max_iterations) is not int or not 0<=max_iterations<=64:
        raise ValueError("expected0..64iterations, excluding bool")
    lo,hi=Fraction(lower),Fraction(upper)
    target,tolerance=Fraction(target_cents),Fraction(tolerance)
    p_lo=annual_cashflow_price(cashflows,lo);p_hi=annual_cashflow_price(cashflows,hi)
    if not p_hi<=target<=p_lo:
        return {"status":"not-bracketed","lower":lo,"upper":hi,"estimate":None,"error_bound":None,"iterations":0}
    if target==p_lo:hi=lo
    elif target==p_hi:lo=hi
    for iterations in range(max_iterations+1):
        if lo==hi:
            return {"status":"exact","lower":lo,"upper":hi,"estimate":lo,"error_bound":Fraction(0),"iterations":iterations}
        if (hi-lo)/2<=tolerance:
            return {"status":"yield-tolerance","lower":lo,"upper":hi,"estimate":(lo+hi)/2,"error_bound":(hi-lo)/2,"iterations":iterations}
        if iterations==max_iterations:
            return {"status":"iteration-limit","lower":lo,"upper":hi,"estimate":(lo+hi)/2,"error_bound":(hi-lo)/2,"iterations":iterations}
        mid=(lo+hi)/2;price=annual_cashflow_price(cashflows,mid)
        if price==target:lo=hi=mid
        elif price>target:lo=mid  # monotone DECREASING price: need a higher yield
        else:hi=mid
    raise AssertionError("unreachable")

cashflows=[(1,500),(2,10500)]
for price,budget in [(10000,8),(9999,0),(20000,8)]:
    result=yield_bracket(cashflows,price,0,Fraction(1,10),Fraction(1,10000),budget)
    print(result["status"],str(result["estimate"]),str(result["error_bound"]),result["iterations"])
